'use strict';
// Web-first portrait revision. Financial simulation keeps running without notifications for spectators.
function financialParticipation128(){let f=S?.financial;return {wealth:!!f?.wealthLots?.some(l=>l.units>0),stocks:!!f?.market?.stocks?.some(s=>s.shares>0)};}
const reportBefore128=financialDailyReport;
financialDailyReport=function(day){reportBefore128(day);let f=financeState(),p=financialParticipation128();if(p.wealth||p.stocks){if(f.lastReportDay>f.lastDailyPopup)f.dailyPending=f.lastReportDay;}else{f.dailyPending=null;delete f.dailyReview;}};
const reviewBefore128=maybeDailyMarketReview;
maybeDailyMarketReview=function(){let p=financialParticipation128(),f=S?.financial;if(!p.wealth&&!p.stocks){if(f){f.dailyPending=null;if(!dailyReviewVisible)delete f.dailyReview;}return;}if(!p.stocks&&f?.dailyPending!=null&&!modalOpen&&!draft&&!bridgeDraft&&!pointers.size&&S.lives>0){f.dailyReview={day:f.dailyPending,wasRunning:!S.paused};f.lastDailyPopup=f.dailyPending;f.dailyPending=null;S.paused=true;showFinancialMarket('wealth');save();updateUI();return;}reviewBefore128();};
const marketBefore128=showFinancialMarket;
showFinancialMarket=function(...args){marketBefore128(...args);if(S.financial?.dailyReview)$('modal-content').innerHTML=$('modal-content').innerHTML.replace('每日股票简报','持仓收益简报');};
financeNotice=function(){if(atlasMenuOpen||modalOpen||draft||bridgeDraft||S.lives<=0)return;let f=financeState(),type=!f.notified.bank&&financialCities('bank').length?'bank':!f.notified.broker&&financialCities('broker').length?'broker':null;if(!type)return;f.notified[type]=true;save();toast(type==='bank'?'银行已可建设 · 在资金中心查看':'证券公司已可建设 · 在资金中心查看');};
farmEligible=function(c){return !!c&&!c.removed&&c.kind!=='bridgehead'&&c.shape===0&&(c.size>=1||!!c.farm);};
const plantBefore128=plantFarm;
plantFarm=function(id){if(S.cities[id]?.size<1)return toast('农田需要中级及以上居住城市');return plantBefore128(id);};
let farmHint128=false;
function farmUnlockHint128(){if(atlasMenuOpen||modalOpen||draft||bridgeDraft)return;let a=agricultureState();if(a.introduced128||a.planted>0)return;let c=S.cities.find(c=>farmEligible(c)&&c.size>=1&&!c.dormant);if(!c||S.points<800)return;a.introduced128=true;farmHint128=true;save();toast('中级居住城市可经营农田 · 点击城市查看');}

// Exactly one card is mounted: no neighbour sliver, and no offscreen accept targets.
let deckPage128=0,deckBatch128='',deckTouch128=null;
function cardMarkup128(e,index){let html=activityCardHTML(e,index),match=/<div class="activity-card activity-front"[^>]*>/.exec(html);if(!match)return html;let start=match.index+match[0].length,end=html.indexOf('</div></div><div class="card-reveal-fx"',start);if(end<0)return html;let inner=html.slice(start,end),actions=inner.search(/<button\b/);if(actions<0)return html;return html.slice(0,start)+'<div class="card-content128">'+inner.slice(0,actions)+'</div><div class="card-actions128">'+inner.slice(actions)+'</div>'+html.slice(end);}
function changeCard128(delta){deckPage128=Math.max(0,Math.min(activityState().offers.length-1,deckPage128+delta));showActivityCards();}
const cardsBefore128=showActivityCards;
showActivityCards=function(){let s=activityState();if(s.active||!s.offers.length)return cardsBefore128();let batch=s.offers.map(e=>e.id).join('|');if(batch!==deckBatch128){deckBatch128=batch;deckPage128=0;}deckPage128=Math.max(0,Math.min(s.offers.length-1,deckPage128));let e=s.offers[deckPage128];S.paused=true;openModal(`<section class="deck128"><header class="deck-heading128"><div><small>城市活动 · 三选一</small><h2>选择下一份邀请</h2></div><button class="close" onclick="closeModal()" aria-label="关闭活动邀请">×</button></header><p class="deck-tip128">翻开邀请后选择一份承接，左右滑动可换卡。</p><div id="activity-reveal-status" class="sr-only" role="status" aria-live="polite"></div><div class="deck-stage128" id="deck-stage128">${cardMarkup128(e,deckPage128)}</div><nav class="deck-pager128" aria-label="活动邀请翻页"><button onclick="changeCard128(-1)" ${deckPage128===0?'disabled':''}>‹ 上一张</button><strong aria-live="polite">${deckPage128+1}<span> / ${s.offers.length}</span></strong><button onclick="changeCard128(1)" ${deckPage128===s.offers.length-1?'disabled':''}>下一张 ›</button></nav><div class="deck-tools128"><button onclick="revealAllActivities()">全部翻开</button><button onclick="skipActivityOffers()">暂不承接</button></div>${s.debt>0?`<p class="deck-debt128">待缴罚款 ¥${s.debt.toFixed(2)}</p>`:''}</section>`);
 let stage=$('deck-stage128');stage?.addEventListener('pointerdown',ev=>{deckTouch128={x:ev.clientX,y:ev.clientY,id:ev.pointerId};});stage?.addEventListener('pointerup',ev=>{let t=deckTouch128;deckTouch128=null;if(!t||t.id!==ev.pointerId)return;let dx=ev.clientX-t.x,dy=ev.clientY-t.y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.6){ev.preventDefault();changeCard128(dx<0?1:-1);}});stage?.addEventListener('pointercancel',()=>{deckTouch128=null;});save();};
// A swipe must never also reveal, locate or accept on the newly mounted card.
let swipeUntil128=0;
document.addEventListener('pointerup',ev=>{let t=deckTouch128;if(t&&t.id===ev.pointerId&&Math.abs(ev.clientX-t.x)>55&&Math.abs(ev.clientX-t.x)>Math.abs(ev.clientY-t.y)*1.6)swipeUntil128=performance.now()+350;},true);
document.addEventListener('click',ev=>{if(performance.now()<swipeUntil128&&ev.target.closest?.('.deck128')){ev.preventDefault();ev.stopImmediatePropagation();}},true);

// Repair directly beside the route quote. Previewing never spends or confirms a route.
function draftDamage128(){if(!draft||draft.type==='air')return [];let c=draftCost(),ids=c.resolved||draft.stops,keys=new Set();for(let i=1;i<ids.length;i++)keys.add(key(S.cities[ids[i-1]],S.cities[ids[i]],draft.type));if(draft.pointer&&ids.length){let a=S.cities[draft.extensionPointer?.city??ids.at(-1)],b=hitCity(draft.pointer);if(b&&a.id!==b.id)keys.add(key(a,b,draft.type));}return [...keys].filter(k=>S.blockages[k]?.cause==='quake').map(k=>({key:k,block:S.blockages[k],quote:repairQuote(k)}));}
function repairInDraft128(k){if(!draft||!draftDamage128().some(x=>x.key===k))return false;let b=S.blockages[k];if(!b||b.status!=='broken')return false;let q=repairQuote(k);if(S.points<q.price){toast('维修还差 ¥'+Math.ceil(q.price-S.points));return false;}spend(q.price,'construction','灾后线路维修');b.status='repairing';b.until=S.day+q.days;save();draftBar();updateUI();toast('已支付 ¥'+q.price+' · 结束拉线并继续运行，维修需要 '+q.days+' 天');return true;}
function repairMarkup128(){return draftDamage128().map(({key:k,block:b,quote:q})=>{let ids=k.split('-').slice(-2).map(Number),name=ids.map(id=>escapeHTML(S.cities[id]?.kind==='bridgehead'?'桥头':S.cities[id]?.name||'路段')).join('—');let label=b.status==='pending'?'等待在途车辆驶离；结束拉线并继续运行后可维修':b.status==='repairing'?'维修中 · 还需 '+Math.max(0,b.until-S.day).toFixed(1)+' 天':S.points<q.price?'资金不足 · 还差 ¥'+Math.ceil(q.price-S.points):'维修需 '+q.days+' 天，完工后恢复通行';return `<div><span><b>地震受损 · ${name}</b><small>${label}</small></span>${b.status==='broken'?`<button onclick="repairInDraft128('${k}')" ${S.points<q.price?'disabled':''}>维修 ¥${q.price}</button>`:''}</div>`;}).join('');}
let repairSignature128='';
function updateRepair128(){let bar=$('drawbar'),html=draft&&!bridgeDraft?repairMarkup128():'';let box=$('draft-repair128');if(!box){box=document.createElement('section');box.id='draft-repair128';bar.appendChild(box);}box.hidden=!html;if(html!==repairSignature128){box.innerHTML=html;repairSignature128=html;}}
const barBefore128=draftBar;draftBar=function(...args){let r=barBefore128(...args);updateRepair128();return r;};
const uiBefore128=updateUI;updateUI=function(...args){let r=uiBefore128(...args);updateRepair128();return r;};
const renderBefore128=render;render=function(){farmUnlockHint128();return renderBefore128();};
